def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    total_players = 1 + len(alive)
    units = int(supply / WATER_REQ)
    severe_scarcity = units <= 1
    moderate_scarcity = units == 2 and total_players > 2

    prev_bids = []
    desperate_opp = False
    rich_opp = False
    for opp in alive:
        if opp.get('budget', 0) > budget * 1.5:
            rich_opp = True
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
            if prev.get('status') == 'lost' or prev.get('hp_after', 10) <= 3:
                desperate_opp = True

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 5:
        urgency += 1
    if no_water_days >= 1:
        urgency += 2

    if not alive:
        base = DAILY_SALARY * 0.22
    elif severe_scarcity:
        if urgency >= 3:
            base = max(DAILY_SALARY * 0.95, highest_prev + 3)
        elif desperate_opp or rich_opp:
            base = max(DAILY_SALARY * 0.82, avg_prev + 2)
        else:
            base = max(DAILY_SALARY * 0.72, highest_prev * 0.92)
    elif moderate_scarcity:
        if urgency >= 3:
            base = max(DAILY_SALARY * 0.78, avg_prev + 1.5)
        elif highest_prev >= DAILY_SALARY * 0.9:
            base = DAILY_SALARY * 0.38
        else:
            base = max(DAILY_SALARY * 0.42, avg_prev * 0.55)
    else:
        if urgency >= 3:
            base = DAILY_SALARY * 0.62
        else:
            base = DAILY_SALARY * 0.24

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget * 0.72)
    elif budget > DAILY_SALARY * 6 and urgency >= 2:
        base = max(base, DAILY_SALARY * 0.88)

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.96)

    bid = min(budget, max(0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 
    MIN_BID_IF_NO_COMPETITION = 1.0 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], MIN_BID_IF_NO_COMPETITION)

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6 

    if my_hp <= 2: 
        base_bid = DAILY_SALARY * 0.98 
    elif my_hp <= 4: 
        base_bid = max(base_bid, DAILY_SALARY * 0.85) 
    elif my_hp <= 6: 
        base_bid = max(base_bid, DAILY_SALARY * 0.7) 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8: 
            if my_hp > 3: 
                base_bid = max(base_bid, DAILY_SALARY * 0.5) 
            else: 
                base_bid = max(base_bid, DAILY_SALARY * 0.95) 
        else: 
            base_bid = max(base_bid, highest_prev_bid + 5.0)
            base_bid = max(base_bid, DAILY_SALARY * 0.65) 

    if current_day >= EPISODE_DAYS - 2: 
        if my_hp <= 4:
            base_bid = max(base_bid, DAILY_SALARY * 0.99) 
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.8) 

    total_water_needed_by_all = WATER_REQ
    for opp in alive_opponents:
        total_water_needed_by_all += opp['water_requirement']

    if current_supply < total_water_needed_by_all:
        num_agents_can_satisfy = current_supply / WATER_REQ if WATER_REQ > 0 else 0

        if num_agents_can_satisfy < 2: 
            if my_hp <= 5: 
                base_bid = max(base_bid, DAILY_SALARY * 0.99) 
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.85) 
        elif current_supply < total_water_needed_by_all * 0.75:
             if my_hp <= 4:
                 base_bid = max(base_bid, DAILY_SALARY * 0.9)
             else:
                 base_bid = max(base_bid, DAILY_SALARY * 0.7)

    final_bid = min(my_budget, base_bid)

    final_bid = max(final_bid, 1.0) 

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Get yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine target bid
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        target = max(DAILY_SALARY * 0.5, highest_prev + 1.0)
    else:
        target = DAILY_SALARY * 0.5

    # Adjust based on personal state
    if my_status['hp'] <= 2:
        target = max(target, DAILY_SALARY * 0.85)
    if my_status['no_water_days'] >= 1:
        target = max(target, DAILY_SALARY * 0.7)

    # Cap by budget and daily salary
    bid = min(my_status['budget'], target, DAILY_SALARY * 0.9)

    # Ensure at least minimal bid to potentially win water if desperate
    if my_status['hp'] <= 2 and bid < DAILY_SALARY * 0.3:
        bid = min(my_status['budget'], DAILY_SALARY * 0.3)

    return max(0.0, bid)
